r.push(await gm.edit_file({ path: ROOT + '/docs/OPEN-ITEMS.md', old: 'The engine INDEX and engine.yaml now record that sha256 in place of the two hashes that matched neither the file nor each other (31a39ac2c2689403920f92bf1231e382cae87c7c3f0055769e5fb0797a60f419 and ' + PIN + ').', new: 'The engine.yaml sha256 field stays the release pin ' + PIN + ', which update-engine-pin.py reads, and the api-reference hash is recorded under api_reference_sha256 in engine.yaml and the engine INDEX. The INDEX previously recorded 31a39ac2c2689403920f92bf1231e382cae87c7c3f0055769e5fb0797a60f419, which matched neither the file nor engine.yaml; it now records the release pin.' }));
