const r = await Promise.all([
  gm.run_shell({ command: "cd /workspace/cleetus && echo '== engine.yaml'; cat .jayzee/engine/engine.yaml; echo '== INDEX header'; sed -n '3p' .jayzee/reference/engine/INDEX.md | cut -c1-400; echo '== sha256sum api-reference.md'; sha256sum .jayzee/engine/api-reference.md; echo '== api_reference_sha256 in engine.yaml'; grep '^api_reference_sha256:' .jayzee/engine/engine.yaml | sed 's/^api_reference_sha256: //' ; echo '== match?'; [ \"$(grep '^api_reference_sha256:' .jayzee/engine/engine.yaml | sed 's/^api_reference_sha256: //')\" = \"$(sha256sum .jayzee/engine/api-reference.md | cut -d' ' -f1)\" ] && echo MATCH || echo MISMATCH" }),
  gm.run_shell({ command: "cd /workspace/cleetus/.jayzee && python3 -I update-engine-pin.py > /tmp/pin.out 2>&1; echo script-exit=$?; tail -n 4 /tmp/pin.out | cut -c1-400; echo '== engine docs untouched?'; cd /workspace/cleetus && git status --short" }),
  gm.run_shell({ command: "cd /workspace/cleetus/.jayzee && python3 -I -c \"import re; src=open('update-engine-pin.py').read(); head=src.split('# ENGINE.md')[0]; ns={}; exec(head.replace('assert toplevel','print(\\\"toplevel-check-reached\\\"); assert toplevel',1).replace('assert toplevel','#assert toplevel',0), ns) if False else None; print('read-path lines:'); print(src[src.index('sha = '):src.index('kernel = ')])\"" }),
]);
return r.map(x => x.output);

const r = await Promise.all([
  gm.run_shell({ command: "cd /workspace/cleetus && echo '== pre-1542dcb sha256 line:'; git show 1542dcb^:.jayzee/engine/engine.yaml | grep '^sha256:'; echo '== current sha256 line:'; grep '^sha256:' .jayzee/engine/engine.yaml; [ \"$(git show 1542dcb^:.jayzee/engine/engine.yaml | grep '^sha256:')\" = \"$(grep '^sha256:' .jayzee/engine/engine.yaml)\" ] && echo RELEASE-PIN-RESTORED-IDENTICAL; echo '== release named by pin docs:'; grep -n 'b5d10e377d04' .jayzee/reference/engine-deep/README.md | cut -c1-120; echo '== git diff'; git diff -- .jayzee/engine/engine.yaml .jayzee/reference/engine/INDEX.md .jayzee/update-engine-pin.py | cut -c1-240" }),
  gm.run_shell({ command: "cd /workspace/cleetus && npm run build > /tmp/b3.out 2>&1; echo build-exit=$?; npm run check > /tmp/c3.out 2>&1; echo npm-check-exit=$?; tail -n 3 /tmp/c3.out | cut -c1-260; node scripts/check-open-items.mjs; echo open-items-exit=$?" }),
]);
return r.map(x => x.output);

const paths = ['.jayzee/engine/engine.yaml', '.jayzee/reference/engine/INDEX.md', '.jayzee/update-engine-pin.py', 'docs/OPEN-ITEMS.md'];
const message = [
  'Keep the release pin in engine.yaml and name the api-reference hash',
  '',
  'The sha256 field in engine.yaml is the release pin that update-engine-pin.py reads. It is restored to b5d10e37, the value before 1542dcb. The api-reference hash moves to api_reference_sha256, which the script does not read. The engine INDEX records both fields.',
  '',
  'update-engine-pin.py now matches the sha256 key exactly and refuses to refresh the engine docs unless .jayzee/engine is its own git repository. In this checkout that path resolves to the cleetus repository, so the script would have recorded cleetus HEAD as the engine HEAD.'
].join('\n');
const add = await gm.git_add({ paths });
const commit = await gm.git_commit({ message, paths, author: 'lanmower' });
const push = await gm.git_push({});
const post = await gm.run_shell({ command: "cd /workspace/cleetus && npm run build > /tmp/b4.out 2>&1; echo build-exit=$?; npm run check > /tmp/c4.out 2>&1; echo npm-check-exit=$?; tail -n 3 /tmp/c4.out | cut -c1-260; node scripts/check-open-items.mjs; echo open-items-exit=$?; node scripts/check-featureset.mjs > /tmp/fs4.out 2>&1; echo featureset-exit=$?; tail -n 1 /tmp/fs4.out; echo '--- origin/main:'; git log origin/main -1; echo '--- status:'; git status --short; echo '(clean)'; echo '--- trailers:'; git log -1 --format=%B | grep -ci 'co-authored-by' ; true" });
return { commit: commit.output, push: push.output, post: post.output };
